#[test]
fn refresh_key_zero_plaintext_validators_reject_oversized_zero_residuals() {
    let params = params();
    let residual_bound = bfv_encrypted_zero_refresh_residual_multiple_bound(&params)
        .expect("encrypted-zero refresh residual bound");
    let oversized_multiple = residual_bound
        .checked_mul(2)
        .and_then(|value| value.checked_add(1))
        .expect("oversized residual multiple fits");
    let oversized_delta = u64::try_from(
        oversized_multiple
            .checked_mul(u128::from(params.plaintext_modulus))
            .expect("oversized residual delta fits u128"),
    )
    .expect("oversized residual delta fits u64");
    let (secret_key, public_key, _) =
        keygen_from_seed(&params, b"bfv-refresh-zero-residual-keygen").expect("keygen");
    let rotation_key = rotation_key_from_seed(
        &params,
        &public_key,
        1,
        b"bfv-refresh-zero-residual-rotation",
    )
    .expect("rotation key");
    let bootstrap_key = bootstrap_key_with_max_refresh_rounds_from_seed(
        &params,
        &public_key,
        "bootstrap-refresh-key",
        2,
        b"bfv-refresh-zero-residual-bootstrap",
    )
    .expect("bootstrap key");

    let rotation_profile =
        decrypt_with_exact_residual_profile(&params, &secret_key, &rotation_key.zero_refresh)
            .expect("rotation refresh residual profile");
    assert!(
        rotation_profile.max_abs_residual_multiple <= residual_bound,
        "generated rotation refresh residual {} must fit bound {residual_bound}",
        rotation_profile.max_abs_residual_multiple
    );
    let bootstrap_profile = decrypt_with_exact_residual_profile(
        &params,
        &secret_key,
        &bootstrap_key.round_refreshes[1],
    )
    .expect("bootstrap refresh residual profile");
    assert!(
        bootstrap_profile.max_abs_residual_multiple <= residual_bound,
        "generated bootstrap refresh residual {} must fit bound {residual_bound}",
        bootstrap_profile.max_abs_residual_multiple
    );

    let mut oversized_rotation = rotation_key;
    oversized_rotation.zero_refresh.c0[0] = add_mod_u64(
        oversized_rotation.zero_refresh.c0[0],
        oversized_delta,
        params.ciphertext_modulus,
    );
    let err = validate_rotation_key_zero_refresh(&params, &secret_key, &oversized_rotation)
        .expect_err("zero-plaintext rotation refresh with oversized residual must be rejected");
    assert!(
        err.to_string().contains("encrypted-zero refresh bound"),
        "unexpected error: {err}"
    );

    let mut oversized_bootstrap = bootstrap_key;
    oversized_bootstrap.round_refreshes[1].c0[0] = add_mod_u64(
        oversized_bootstrap.round_refreshes[1].c0[0],
        oversized_delta,
        params.ciphertext_modulus,
    );
    let err = validate_bootstrap_key_zero_refreshes(&params, &secret_key, &oversized_bootstrap)
        .expect_err("zero-plaintext bootstrap refresh with oversized residual must be rejected");
    assert!(
        err.to_string().contains("round_refreshes[1]"),
        "unexpected error: {err}"
    );
    assert!(
        err.to_string().contains("encrypted-zero refresh bound"),
        "unexpected error: {err}"
    );
}

#[test]
fn evaluation_key_bundle_zero_refresh_diagnostics_cover_all_public_masks() {
    let material = evaluation_key_adversarial_material();
    let bootstrap_key = bootstrap_key_with_max_refresh_rounds_from_seed(
        &material.params,
        &material.public_key,
        "bootstrap-refresh-key",
        2,
        b"bfv-bundle-zero-refresh-bootstrap",
    )
    .expect("bootstrap key");
    let bundle = BfvEvaluationKeyBundle {
        relinearization_key: material.relinearization_key.clone(),
        rotation_keys: vec![material.rotation_key.clone()],
        galois_keys: vec![material.galois_key.clone()],
        bootstrap_key: Some(bootstrap_key),
    };

    bundle
        .validate_zero_refreshes(&material.params, &material.secret_key)
        .expect("generated bundle refreshes decrypt to zero");

    let mut nonzero_rotation = bundle.clone();
    nonzero_rotation.rotation_keys[0].zero_refresh = add_plain_scalar(
        &material.params,
        &nonzero_rotation.rotation_keys[0].zero_refresh,
        1,
    )
    .expect("add non-zero plaintext to rotation refresh");
    let err = nonzero_rotation
        .validate_zero_refreshes(&material.params, &material.secret_key)
        .expect_err("non-zero bundle rotation refresh must be rejected");
    assert!(
        err.to_string().contains("rotation_keys[0]"),
        "unexpected error: {err}"
    );

    let mut nonzero_bootstrap = bundle;
    let bootstrap_key = nonzero_bootstrap
        .bootstrap_key
        .as_mut()
        .expect("bundle carries bootstrap key");
    bootstrap_key.round_refreshes[1] =
        add_plain_scalar(&material.params, &bootstrap_key.round_refreshes[1], 1)
            .expect("add non-zero plaintext to bootstrap refresh");
    let err = nonzero_bootstrap
        .validate_zero_refreshes(&material.params, &material.secret_key)
        .expect_err("non-zero bundle bootstrap refresh must be rejected");
    assert!(
        err.to_string().contains("round_refreshes[1]"),
        "unexpected error: {err}"
    );
}

#[test]
fn evaluation_key_bundle_secret_consistency_rejects_tampered_key_switch_entries() {
    let material = evaluation_key_adversarial_material();
    let bundle = BfvEvaluationKeyBundle {
        relinearization_key: material.relinearization_key.clone(),
        rotation_keys: vec![material.rotation_key.clone()],
        galois_keys: vec![material.galois_key.clone()],
        bootstrap_key: None,
    };

    bundle
        .validate_secret_key_consistency(&material.params, &material.secret_key)
        .expect("generated evaluation-key bundle is consistent with the secret key");

    let mut non_plaintext_residue = bundle.clone();
    non_plaintext_residue.relinearization_key.entries[0].b[0] = add_mod_u64(
        non_plaintext_residue.relinearization_key.entries[0].b[0],
        1,
        material.params.ciphertext_modulus,
    );
    let err = non_plaintext_residue
        .validate_secret_key_consistency(&material.params, &material.secret_key)
        .expect_err("non-plaintext-multiple relin residue must be rejected");
    assert!(
        err.to_string().contains("non-plaintext-multiple"),
        "unexpected error: {err}"
    );

    let mut oversized_error = bundle.clone();
    oversized_error.relinearization_key.entries[0].b[0] = add_mod_u64(
        oversized_error.relinearization_key.entries[0].b[0],
        material.params.plaintext_modulus * 2,
        material.params.ciphertext_modulus,
    );
    let err = oversized_error
        .validate_secret_key_consistency(&material.params, &material.secret_key)
        .expect_err("oversized relin error multiple must be rejected");
    assert!(
        err.to_string().contains("BFV error bound"),
        "unexpected error: {err}"
    );

    let mut tampered_galois = bundle;
    tampered_galois.galois_keys[0].entries[0].b[0] = add_mod_u64(
        tampered_galois.galois_keys[0].entries[0].b[0],
        1,
        material.params.ciphertext_modulus,
    );
    let err = tampered_galois
        .validate_secret_key_consistency(&material.params, &material.secret_key)
        .expect_err("tampered Galois entry must be rejected");
    assert!(
        err.to_string().contains("galois_keys[0]"),
        "unexpected error: {err}"
    );
}

#[test]
fn bootstrap_refresh_rns_exact_matches_scalar_refresh() {
    let params = ram_lfe_bfv_parameters_v1();
    let chain = registered_bfv_rns_modulus_chain(&params).expect("registered RNS chain");
    let (secret_key, public_key, _) =
        keygen_from_seed(&params, b"bfv-bootstrap-rns-keygen").expect("keygen");
    let ciphertext = encrypt_from_seed(
        &params,
        &public_key,
        &[77],
        b"bfv-bootstrap-rns-input-ciphertext",
    )
    .expect("encrypt");
    let bootstrap_key = bootstrap_key_with_max_refresh_rounds_from_seed(
        &params,
        &public_key,
        "bootstrap-refresh-key",
        2,
        b"bfv-bootstrap-rns-zero-refresh",
    )
    .expect("bootstrap key");

    let scalar_round_zero =
        bootstrap_ciphertext(&params, &bootstrap_key, &ciphertext).expect("scalar round zero");
    let rns_round_zero =
        bootstrap_ciphertext_rns_exact(&params, &chain, &bootstrap_key, &ciphertext)
            .expect("RNS exact round zero");
    let registered_round_zero =
        bootstrap_ciphertext_registered_rns_exact(&params, &bootstrap_key, &ciphertext)
            .expect("registered RNS exact round zero");
    assert_eq!(rns_round_zero, scalar_round_zero);
    assert_eq!(registered_round_zero, scalar_round_zero);

    let scalar_indexed = bootstrap_ciphertext_round(&params, &bootstrap_key, &ciphertext, 1)
        .expect("scalar indexed refresh");
    let rns_indexed =
        bootstrap_ciphertext_rns_exact_round(&params, &chain, &bootstrap_key, &ciphertext, 1)
            .expect("RNS exact indexed refresh");
    let registered_indexed =
        bootstrap_ciphertext_registered_rns_exact_round(&params, &bootstrap_key, &ciphertext, 1)
            .expect("registered RNS exact indexed refresh");
    assert_eq!(rns_indexed, scalar_indexed);
    assert_eq!(registered_indexed, scalar_indexed);

    let scalar = bootstrap_ciphertext_rounds(&params, &bootstrap_key, &ciphertext, 2)
        .expect("scalar multi-round refresh");
    let rns =
        bootstrap_ciphertext_rns_exact_rounds(&params, &chain, &bootstrap_key, &ciphertext, 2)
            .expect("RNS exact multi-round refresh");
    let registered_rns =
        bootstrap_ciphertext_registered_rns_exact_rounds(&params, &bootstrap_key, &ciphertext, 2)
            .expect("registered RNS exact multi-round refresh");

    assert_eq!(rns, scalar);
    assert_eq!(registered_rns, scalar);
    assert_eq!(
        decrypt(&params, &secret_key, &rns).expect("decrypt RNS refresh")[0],
        77
    );

    let mut mismatched_zero_refresh = bootstrap_key.clone();
    mismatched_zero_refresh.zero_refresh = mismatched_zero_refresh.round_refreshes[1].clone();
    assert_error_contains(
        bootstrap_ciphertext_rns_exact_round(
            &params,
            &chain,
            &mismatched_zero_refresh,
            &ciphertext,
            0,
        ),
        "zero_refresh must match round_refreshes[0]",
        "RNS exact bootstrap refresh must reject zero_refresh drift before applying a round",
    );

    let mut duplicated_round_refresh = bootstrap_key.clone();
    duplicated_round_refresh.round_refreshes[1] =
        duplicated_round_refresh.round_refreshes[0].clone();
    assert_error_contains(
        bootstrap_ciphertext_registered_rns_exact_rounds(
            &params,
            &duplicated_round_refresh,
            &ciphertext,
            2,
        ),
        "duplicate round refresh ciphertext",
        "registered RNS exact bootstrap refresh must reject aliased refresh material before applying rounds",
    );
    let err =
        bootstrap_ciphertext_rns_exact_rounds(&params, &chain, &bootstrap_key, &ciphertext, 0)
            .expect_err("zero-round RNS bootstrap refresh must be rejected");
    assert!(
        err.to_string().contains("at least one round"),
        "unexpected error: {err}"
    );
    let err =
        bootstrap_ciphertext_rns_exact_rounds(&params, &chain, &bootstrap_key, &ciphertext, 3)
            .expect_err("over-key-capacity RNS bootstrap refresh must be rejected");
    assert!(
        err.to_string().contains("max_refresh_rounds"),
        "unexpected error: {err}"
    );
}

#[test]
fn rotation_key_rotates_and_refreshes_ciphertext_slots() {
    let params = params();
    let (secret_key, public_key, _) =
        keygen_from_seed(&params, b"bfv-rotation-keygen").expect("keygen");
    let slots = [10_u64, 20, 30]
        .into_iter()
        .enumerate()
        .map(|(index, value)| {
            encrypt_from_seed(
                &params,
                &public_key,
                &[value],
                format!("bfv-rotation-slot-{index}").as_bytes(),
            )
            .expect("encrypt slot")
        })
        .collect::<Vec<_>>();
    let rotation_key =
        rotation_key_from_seed(&params, &public_key, 1, b"bfv-rotation-zero-refresh")
            .expect("rotation key");

    let mut inert_rotation_key = rotation_key.clone();
    inert_rotation_key.zero_refresh = BfvCiphertext {
        c0: zero_poly(&params),
        c1: zero_poly(&params),
    };
    validate_rotation_key(&params, &inert_rotation_key)
        .expect("shape validation remains available for inert rotation diagnostics");
    assert_error_contains(
        validate_rotation_key_zero_refresh(&params, &secret_key, &inert_rotation_key),
        "rotation key zero_refresh must not be an all-zero ciphertext",
        "key-owner rotation diagnostics must reject inert zero_refresh material",
    );
    assert_error_contains(
        rotate_ciphertext_slots_left(&params, &inert_rotation_key, &slots),
        "rotation key zero_refresh must not be an all-zero ciphertext",
        "direct outer-slot rotation must reject inert zero_refresh material before applying refresh",
    );

    let rotated =
        rotate_ciphertext_slots_left(&params, &rotation_key, &slots).expect("rotate slots");

    assert_eq!(rotated.len(), slots.len());
    assert_ne!(
        rotated,
        vec![slots[1].clone(), slots[2].clone(), slots[0].clone()]
    );
    let plaintexts = rotated
        .iter()
        .map(|slot| decrypt(&params, &secret_key, slot).expect("decrypt")[0])
        .collect::<Vec<_>>();
    assert_eq!(plaintexts, vec![20, 30, 10]);
}

#[test]
fn rotation_slot_residual_bounds_track_public_refresh() {
    let params = params();
    let (secret_key, public_key, _) =
        keygen_from_seed(&params, b"bfv-rotation-bound-keygen").expect("keygen");
    let slots = [10_u64, 20, 30]
        .into_iter()
        .enumerate()
        .map(|(index, value)| {
            encrypt_from_seed(
                &params,
                &public_key,
                &[value],
                format!("bfv-rotation-bound-slot-{index}").as_bytes(),
            )
            .expect("encrypt slot")
        })
        .collect::<Vec<_>>();
    let rotation_key =
        rotation_key_from_seed(&params, &public_key, 1, b"bfv-rotation-bound-refresh")
            .expect("rotation key");
    let input_bound =
        bfv_encrypted_zero_refresh_residual_multiple_bound(&params).expect("input bound");
    let mut inert_rotation_key = rotation_key.clone();
    inert_rotation_key.zero_refresh = BfvCiphertext {
        c0: zero_poly(&params),
        c1: zero_poly(&params),
    };
    validate_rotation_key(&params, &inert_rotation_key)
        .expect("shape validation remains available for inert rotation bound diagnostics");
    assert_error_contains(
        bfv_rotate_slots_left_output_residual_multiple_bounds(
            &params,
            &inert_rotation_key,
            &[input_bound; 3],
        ),
        "rotation key zero_refresh must not be an all-zero ciphertext",
        "outer-slot rotation residual bounds must reject inert zero_refresh material",
    );
    let bounds = bfv_rotate_slots_left_output_residual_multiple_bounds(
        &params,
        &rotation_key,
        &[input_bound, input_bound * 2, input_bound * 3],
    )
    .expect("rotation output residual bounds");
    assert_eq!(
        bounds,
        vec![input_bound * 3, input_bound * 4, input_bound * 2]
    );

    let rotated =
        rotate_ciphertext_slots_left(&params, &rotation_key, &slots).expect("rotate slots");
    let expected_plaintexts = [20, 30, 10];
    for (index, (slot, &bound)) in rotated.iter().zip(&bounds).enumerate() {
        let profile = validate_ciphertext_exact_residual_multiple_bound(
            &params,
            &secret_key,
            slot,
            bound,
            &format!("rotation output[{index}]"),
        )
        .expect("rotation output fits propagated residual bound");
        assert_eq!(profile.plaintext[0], expected_plaintexts[index]);
    }

    let capacity = centered_residual_multiple_capacity(&params);
    let err = bfv_rotate_slots_left_output_residual_multiple_bounds(
        &params,
        &rotation_key,
        &[capacity + 1, input_bound, input_bound],
    )
    .expect_err("input bounds above capacity must be rejected");
    assert!(
        err.to_string().contains("RotateLeft input[0]"),
        "unexpected error: {err}"
    );

    let err = bfv_rotate_slots_left_output_residual_multiple_bounds(
        &params,
        &rotation_key,
        &[0, 0, capacity],
    )
    .expect_err("output bounds above capacity must be rejected");
    assert!(
        err.to_string().contains("add output residual bound")
            || err.to_string().contains("RotateLeft output"),
        "unexpected error: {err}"
    );

    let malformed_rotation_key = BfvRotationKey {
        rotation_steps: 1,
        zero_refresh: BfvCiphertext {
            c0: Vec::new(),
            c1: Vec::new(),
        },
    };
    let err = bfv_rotate_slots_left_output_residual_multiple_bounds(
        &params,
        &malformed_rotation_key,
        &[capacity + 1, input_bound, input_bound],
    )
    .expect_err("oversized exact outer rotation bounds must be rejected before key shapes");
    assert!(
        err.to_string().contains("RotateLeft input[0]"),
        "unexpected error: {err}"
    );
    let malformed_full_cycle_key = BfvRotationKey {
        rotation_steps: 3,
        zero_refresh: BfvCiphertext {
            c0: Vec::new(),
            c1: Vec::new(),
        },
    };
    let err = bfv_rotate_slots_left_output_residual_multiple_bounds(
        &params,
        &malformed_full_cycle_key,
        &[input_bound; 3],
    )
    .expect_err("full-cycle exact outer rotations must be rejected before key shapes");
    assert!(
        err.to_string().contains("full slot cycle"),
        "unexpected error: {err}"
    );
    let err = bfv_rotate_slots_left_output_residual_multiple_bounds(
        &params,
        &malformed_rotation_key,
        &[input_bound; 3],
    )
    .expect_err("malformed exact outer rotation keys must be rejected after public preflight");
    assert!(
        err.to_string().contains("ciphertext"),
        "unexpected error: {err}"
    );

    let err = bfv_rotate_slots_left_output_residual_multiple_bounds(&params, &rotation_key, &[])
        .expect_err("empty rotation bound inputs must be rejected");
    assert!(
        err.to_string().contains("at least one ciphertext slot"),
        "unexpected error: {err}"
    );

    let full_cycle_key =
        rotation_key_from_seed(&params, &public_key, 3, b"bfv-rotation-bound-full-cycle")
            .expect("full-cycle key is valid until slot count is known");
    let err = bfv_rotate_slots_left_output_residual_multiple_bounds(
        &params,
        &full_cycle_key,
        &[input_bound; 3],
    )
    .expect_err("full-cycle rotations must be rejected");
    assert!(
        err.to_string().contains("full slot cycle"),
        "unexpected error: {err}"
    );
}

